ALTER TABLE "review" DROP CONSTRAINT "review_valid";--> statement-breakpoint
ALTER TABLE "review" ADD COLUMN "allow_social_use" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "review" ADD COLUMN "social_permission_version" text;--> statement-breakpoint
ALTER TABLE "review" ADD CONSTRAINT "review_valid" CHECK ("review"."version">0 and ("review"."allow_social_use"=false or ("review"."social_permission_version" is not null and "review"."social_permission_version"='public-review-social-v1')) and "review"."status" in ('pending','published','hidden','withdrawn') and "review"."request_fingerprint" ~ '^[a-f0-9]{64}$' and (("review"."status"='withdrawn' and "review"."public_name" is null and "review"."body" is null and "review"."rating" is null and "review"."reply" is null and "review"."moderation_reason" is null and "review"."share_services"=false and "review"."allow_social_use"=false) or ("review"."status"<>'withdrawn' and "review"."public_name" is not null and length(btrim("review"."public_name")) between 1 and 80 and "review"."body" is not null and length(btrim("review"."body")) between 1 and 2000 and "review"."rating" is not null and "review"."rating" between 1 and 5)) and ("review"."reply" is null or length(btrim("review"."reply")) between 1 and 1000) and ("review"."status"<>'published' or "review"."published_at" is not null) and ("review"."status"<>'hidden' or ("review"."moderation_reason" is not null and length(btrim("review"."moderation_reason")) between 1 and 300)));